UPDATE lessons SET title='Year 4, Week 18, Lesson 1: Peer influence and making choices', data=json_patch(data,'{"child_mission":"Peer influence can be positive or negative; making choices means checking safety, rules and your values before agreeing.","coming_soon":null,"duration_minutes":55,"evidence_instructions":"Save the independent response, specific revisions and both short-answer explanations; record oral evidence for speaking tasks.","explicit_teaching":null,"extension":"Apply the same idea to a new game or situation, then compare two choices for safety and inclusion.","follow_up_challenges":null,"guided_practice":"PRACTISE BEFORE READING THE FEEDBACK\nSort: join a study group; dare to vandalise; invite a left-out classmate.\n\nFEEDBACK\nPositive; negative; positive.\n\nWATCH FOR\n“Everyone is doing it” is not a safety check.","hoard_words":null,"independent_task":"INDEPENDENT EVIDENCE\nCreate a choice checklist (safe? kind? allowed? true to me?). Apply to six scenarios.\n\nWrite a short reflection naming one choice you changed and why. Any movement is optional, adult-supervised and can be done in a gentler way or described instead.","interactive_activities":null,"learning_area":"PDHPE","learning_intention":"Peer influence can be positive or negative; making choices means checking safety, rules and your values before agreeing.","lesson_number":1,"lesson_role":"Learn and discuss","materials":["Paper or typed answer space","Pencil","Clear, safe movement space with an adult nearby for any physical activity","Optional: soft ball, cushion or water bottle"],"offline_alternative":"Use paper and pencil to complete the original task, then retain a photograph or short parent observation as evidence.","outcome_codes":["PH2-RRS-01"],"parent_notes":"Parent: Marking guidance for the independent task: Create a choice checklist (safe? kind? allowed? true to me?). Apply to six scenarios. Accept equivalent original responses that show the same skill.\n\nParent: Written model 1: Original response on new material: Positive; negative; positive. Reasoning: I used peer by attending to influence rather than copying the worked model.\n\nParent: Written model 2: Common error: “Everyone is doing it” is not a safety check. Correction: Positive; negative; positive. Why: the correction restores accurate use of peer.\n\nParent: Likely misconception: “Everyone is doing it” is not a safety check. Keep sample answers out of the child role.\n\nParent: Short-answer focus 1: Produce a fresh example demonstrating peer on new material (not the worked model). Explain the particular words, sources or choices that make it work.\n\nParent: Short-answer focus 2: Name one likely error with peer, correct it, and explain why the correction helps a reader or audience.\n\nParent: Marking notes: Require independently produced work with a specific supporting detail. / Require misconception + correction + purpose-linked reason..","pass":1,"pass_mark":0.9,"planner_fields":null,"planner_intro":null,"planner_title":null,"printable_resource":null,"quiz":[{"correct_index":2,"explanation":"Positive; negative; positive. This matches the lesson skill for peer.","options":["Ignore the safety rule because the first idea looked exciting.","Copy the example and call that independent work.","Positive; negative; positive.","“Everyone is doing it” is not a safety check."],"question":"Sort: join a study group; dare to vandalise; invite a left-out classmate. Which response is most accurate?","type":"multiple_choice"},{"correct_index":1,"explanation":"“Everyone is doing it” is not a safety check. That misconception weakens accuracy; the other choices align with the lesson idea.","options":["Careful use of influence with clear evidence.","“Everyone is doing it” is not a safety check.","Peer influence can be positive or negative; making choices means checking safety, rules and your values before agreeing.","Positive; negative; positive."],"question":"Which statement is a common mistake when practising peer?","type":"multiple_choice"},{"correct_index":1,"explanation":"Understanding is shown by new evidence and named influence, not by copying the model.","options":["Treat a skipped permission or safety step as if it did not matter.","Apply the idea with new evidence and name the influence used.","Repeat the worked example wording with no new evidence.","Choose randomly because any option could be right."],"question":"A learner is practising peer. Which approach best shows understanding?","type":"multiple_choice"},{"correct_index":2,"explanation":"Positive; negative; positive. uses safe, healthy, respectful choices appropriately for this lesson.","options":["Ignore the safety rule because the first idea looked exciting.","Copy the example and call that independent work.","Positive; negative; positive.","“Everyone is doing it” is not a safety check."],"question":"Which response best shows careful thinking about peer?","type":"multiple_choice"},{"correct_index":0,"explanation":"Strong answers name specific evidence and what it shows.","options":["Name a specific source, cue or example and say what it shows about peer.","Make a bigger claim without naming any source or cue.","Copy a classmate’s sentence with no local detail.","“Everyone is doing it” is not a safety check."],"question":"Which habit strengthens evidence about influence?","type":"multiple_choice"},{"correct_index":0,"explanation":"The stronger choice matches the taught idea with concrete detail.","options":["Example: friends invite extra practice (positive) vs dare to exclude someone (negative).","“Everyone is doing it” is not a safety check.","Treat a skipped permission or safety step as if it did not matter.","Ignore the safety rule because the first idea looked exciting."],"question":"Using this lesson idea — Peer influence can be positive or negative; making choices means checking safety, rules and your values… — which choice is best?","type":"multiple_choice"},{"correct_index":0,"explanation":"Respect and accuracy mean checking evidence and honouring limits/protocols.","options":["Check facts/cues, acknowledge limits, and avoid inventing details.","Invent missing details to make the answer sound complete.","Ignore safety or cultural protocols to finish faster.","Treat every online claim as equally reliable."],"question":"Which action shows respect and accuracy together?","type":"multiple_choice"},{"correct_index":3,"explanation":"Independence requires a new example that still uses the skill.","options":["Retype the worked example with no new example.","Copy the example and call that independent work.","“Everyone is doing it” is not a safety check.","Create a choice checklist (safe? kind? allowed? true to me?). Apply to six scenarios."],"question":"Which task best shows independent use of peer?","type":"multiple_choice"},{"explanation":"Independent evidence on new material demonstrates the skill; copying the model does not.","marking_guide":"Require independently produced work with a specific supporting detail.","question":"Produce a fresh example demonstrating peer on new material (not the worked model). Explain the particular words, sources or choices that make it work.","sample_answer":"Original response on new material: Positive; negative; positive. Reasoning: I used peer by attending to influence rather than copying the worked model.","type":"short_answer"},{"explanation":"A useful correction changes the inaccurate idea or method and explains why.","marking_guide":"Require misconception + correction + purpose-linked reason.","question":"Name one likely error with peer, correct it, and explain why the correction helps a reader or audience.","sample_answer":"Common error: “Everyone is doing it” is not a safety check. Correction: Positive; negative; positive. Why: the correction restores accurate use of peer.","type":"short_answer"}],"resources":null,"response_prompt":"Include your independent evidence and reflection, with reasons where requested. Share only what you feel comfortable sharing.","review_status":"unreviewed","seed_key":"s2-pdhpe-y4-w18-l1","sort_activity":null,"source_note":"Proposed Stage 2 NESA PDHPE alignment using catalogue outcome codes (PH2-*); content-point mapping remains pending human review. Physical activities are optional, adult-supervised and adaptable; no child is required to share personal details.","spelling":null,"spelling_focus":null,"stage":"S2","stage_hints":{"accept":["Today you will practise peer.","Read the mission before you start moving or deciding.","Keep your own safety and everyone''s inclusion in view."],"guided":["Attempt the guided prompt without looking ahead.","Afterwards, compare your reasons with the feedback.","Adjust anything that does not keep everyone safe and included."],"learn":["Study how the first demonstration is built.","Point to the cue or rule that carries the idea.","Then write the reason without copying every sentence."],"quiz":["Read every option before you choose.","Eliminate answers that ignore safety, consent or inclusion.","Prefer a reasoned, respectful choice over one that merely looks fun."],"submit":["Confirm that your reasons and reflection are both present.","Proofread names, steps and safety words.","Make sure the final evidence matches the lesson purpose."],"teach0":["Read the stage title and find the worked example.","Name one exact cue, rule or choice before you decide.","Think through the small prompt before opening the comparison."],"teach1":["Return to the example and list the key cues.","Say what each cue does for safety, health or friendship.","A final label alone is weaker than a stated reason."],"teach2":["Compare an unsafe or unkind choice with a better one.","Change the choice or strategy, not only the words.","Name the mistake you are repairing."],"teach3":["Choose a fresh place, game or situation that still uses the same skill.","Write one reason in your own words.","Do not retype the worked example as your answer."],"write":["Follow every part of the independent instructions.","Include original reasons and a short reflection.","Save work that shows the skill in a new situation."]},"subject":"Health, Wellbeing and Relationships","success_criteria":["I can use peer with a specific example from this lesson.","I can identify influence and explain why it matters.","I can practise choice independently on a new prompt.","I can notice values needs and correct a likely mistake."],"suspense_builder":null,"teach_steps":[{"check":{"correct_index":2,"explanation":"Peer influence can be positive or negative; making choices means checking safety, rules and your values before agreeing. Supported choices follow the actual cues, rules and purpose of the task.","options":["An answer copied without understanding.","A guess with no reason.","Peer influence can be positive or negative; making choices means checking safety, rules and your values before agreeing.","A choice unrelated to safety, health or respect."],"question":"Which choice best shows accurate use of this idea about peer?","type":"multiple_choice"},"example":"WORKED MODEL\nExample: friends invite extra practice (positive) vs dare to exclude someone (negative).\n\nTRY FIRST\nSort: join a study group; dare to vandalise; invite a left-out classmate.\n\nFEEDBACK\nPositive; negative; positive.","explain":"Peer influence can be positive or negative; making choices means checking safety, rules and your values before agreeing.\n\nWHY IT MATTERS\nThis helps the learner make safe, healthy and respectful choices using clear cues and reasons, rather than guessing or copying others. Every choice keeps bodies safe and includes everyone.\n\nHOW TO WORK\nRead the worked example and name the cues, rules or choices that carry the idea. Before looking at the correction, make your own attempt using the exact question provided. For any movement, use a clear space, ask an adult to be nearby, move at your own comfortable level and stop if anything hurts or feels unsafe. You may always choose a gentler version or only describe the movement. One deliberate, reasoned change is more useful than a longer answer.","icon":"📖","notice":"“Everyone is doing it” is not a safety check. Change the choice or strategy, not just the wording.","title":"Understand and demonstrate","visual":[{"alt":"Peer influence.","caption":"Values before agree.","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 660 150\"><rect x=\"10\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#fff4ea\" stroke=\"#b87445\"/><rect x=\"340\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#e8f5ed\" stroke=\"#297a61\"/><g font-size=\"16\" fill=\"#263948\"><text x=\"28\" y=\"42\">Influence</text><text x=\"28\" y=\"78\">+ or −</text><text x=\"358\" y=\"42\">Checklist</text><text x=\"358\" y=\"78\">safe kind allowed</text></g></svg>"}],"visual_before":[{"episode":{"scenes":[{"bg":"room","lines":[{"text":"I can see the example, but I am not sure which cue or rule matters most.","who":"pip"},{"text":"Name the cues, rules or choices that keep everyone safe and included before you decide.","who":"juno"},{"text":"I will try the prompt myself, then compare with the feedback.","who":"pip"},{"pause_after":true,"text":"Pause here. Use this example: Example: friends invite extra practice (positive) vs dare to exclude someone (negative). Then write your own reasons.","who":"juno"}]}],"title":"Talk through the first model","transcript":"Pip: I can see the example, but I am not sure which cue or rule matters most.\nJuno: Name the cues, rules or choices that keep everyone safe and included before you decide.\nPip: I will try the prompt myself, then compare with the feedback.\nJuno: Pause here. Use this example: Example: friends invite extra practice (positive) vs dare to exclude someone (negative). Then write your own reasons."}}]},{"check":{"correct_index":3,"explanation":"Make the PDHPE idea visible: name the body cue, safety rule or wellbeing strategy you used and say why it helps you or others. Supported choices follow the actual cues, rules and purpose of the task.","options":["A choice unrelated to safety, health or respect.","An answer copied without understanding.","A guess with no reason.","Make the PDHPE idea visible: name the body cue, safety rule or wellbeing strategy you used and say why it helps you or others."],"question":"Which choice best shows accurate use of this idea about peer?","type":"multiple_choice"},"example":"WORKED MODEL\nExample: friends invite extra practice (positive) vs dare to exclude someone (negative). Look at each cue, rule or choice that carries the idea.\n\nTRY FIRST\nList the key cues, rules or choices from the example and say what each one does for safety, health or relationships.\n\nFEEDBACK\nThe most useful reasoning names the cue, rule or strategy and the reason it helps, not only a label such as \"good\".","explain":"Make the PDHPE idea visible: name the body cue, safety rule or wellbeing strategy you used and say why it helps you or others.\n\nWHY IT MATTERS\nThis helps the learner make safe, healthy and respectful choices using clear cues and reasons, rather than guessing or copying others. Every choice keeps bodies safe and includes everyone.\n\nHOW TO WORK\nRead the worked example and name the cues, rules or choices that carry the idea. Before looking at the correction, make your own attempt using the exact question provided. For any movement, use a clear space, ask an adult to be nearby, move at your own comfortable level and stop if anything hurts or feels unsafe. You may always choose a gentler version or only describe the movement. One deliberate, reasoned change is more useful than a longer answer.","icon":"📖","notice":"Writing only a final label without a reason does not show PDHPE thinking. Change the choice or strategy, not just the wording.","title":"Show the reasoning","visual":[{"alt":"Choice checklist.","caption":"Sort influence.","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 660 150\"><rect x=\"10\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#fff4ea\" stroke=\"#b87445\"/><rect x=\"340\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#e8f5ed\" stroke=\"#297a61\"/><g font-size=\"16\" fill=\"#263948\"><text x=\"28\" y=\"42\">Six scenarios</text><text x=\"28\" y=\"78\">checklist</text><text x=\"358\" y=\"42\">Risk</text><text x=\"358\" y=\"78\">everyone does it</text></g></svg>"}]},{"check":{"correct_index":0,"explanation":"Use an intentionally unsafe or unhelpful choice as a comparison. Name the specific PDHPE error, then show the safer or more respectful choice. Supported choices follow the actual cues, rules and purpose of the task.","options":["Use an intentionally unsafe or unhelpful choice as a comparison. Name the specific PDHPE error, then show the safer or more respectful choice.","A choice unrelated to safety, health or respect.","An answer copied without understanding.","A guess with no reason."],"question":"Which choice best shows accurate use of this idea about peer?","type":"multiple_choice"},"example":"WORKED MODEL\n“Everyone is doing it” is not a safety check. Here is a more helpful example: Example: friends invite extra practice (positive) vs dare to exclude someone (negative).\n\nTRY FIRST\nDescribe why the warned-against choice does not work, then write a safer, kinder or healthier choice with a reason.\n\nFEEDBACK\nPositive; negative; positive.","explain":"Use an intentionally unsafe or unhelpful choice as a comparison. Name the specific PDHPE error, then show the safer or more respectful choice.\n\nWHY IT MATTERS\nThis helps the learner make safe, healthy and respectful choices using clear cues and reasons, rather than guessing or copying others. Every choice keeps bodies safe and includes everyone.\n\nHOW TO WORK\nRead the worked example and name the cues, rules or choices that carry the idea. Before looking at the correction, make your own attempt using the exact question provided. For any movement, use a clear space, ask an adult to be nearby, move at your own comfortable level and stop if anything hurts or feels unsafe. You may always choose a gentler version or only describe the movement. One deliberate, reasoned change is more useful than a longer answer.","icon":"📖","notice":"Changing the wording without changing the choice does not fix the error. “Everyone is doing it” is not a safety check. Change the choice or strategy, not just the wording.","title":"Test a misconception"},{"check":{"correct_index":3,"explanation":"Use the same PDHPE idea in a new place, game or situation, not a copy of the example. Review safety, fairness and inclusion. Supported choices follow the actual cues, rules and purpose of the task.","options":["A choice unrelated to safety, health or respect.","An answer copied without understanding.","A guess with no reason.","Use the same PDHPE idea in a new place, game or situation, not a copy of the example. Review safety, fairness and inclusion."],"question":"Which choice best shows accurate use of this idea about peer?","type":"multiple_choice"},"example":"WORKED MODEL\nPeer influence can be positive or negative; making choices means checking safety, rules and your values before agreeing. Now choose a different situation to show you can transfer the idea.\n\nTRY FIRST\nDescribe or practise one fresh situation that uses the same skill and write a short reason for your choice.\n\nFEEDBACK\nThe new situation should use the same PDHPE idea as the example, but happen in a different place or with different people.","explain":"Use the same PDHPE idea in a new place, game or situation, not a copy of the example. Review safety, fairness and inclusion.\n\nWHY IT MATTERS\nThis helps the learner make safe, healthy and respectful choices using clear cues and reasons, rather than guessing or copying others. Every choice keeps bodies safe and includes everyone.\n\nHOW TO WORK\nRead the worked example and name the cues, rules or choices that carry the idea. Before looking at the correction, make your own attempt using the exact question provided. For any movement, use a clear space, ask an adult to be nearby, move at your own comfortable level and stop if anything hurts or feels unsafe. You may always choose a gentler version or only describe the movement. One deliberate, reasoned change is more useful than a longer answer.","icon":"📖","notice":"Repeating the worked example cannot show transfer to a new situation. Change the choice or strategy, not just the wording.","title":"Transfer to a new situation"}],"title":"Year 4, Week 18, Lesson 1: Peer influence and making choices","unit_number":4,"unit_title":"Relationships, communication and respect","week":18,"week_in_unit":3,"word_challenges":null,"worked_example":"WORK THROUGH THIS\nExample: friends invite extra practice (positive) vs dare to exclude someone (negative).\n\nWrite what makes this example safe, healthy or respectful, naming the cues, rules or choices used.","worked_visuals":[{"alt":"Peer influence.","caption":"Values before agree.","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 660 150\"><rect x=\"10\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#fff4ea\" stroke=\"#b87445\"/><rect x=\"340\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#e8f5ed\" stroke=\"#297a61\"/><g font-size=\"16\" fill=\"#263948\"><text x=\"28\" y=\"42\">Influence</text><text x=\"28\" y=\"78\">+ or −</text><text x=\"358\" y=\"42\">Checklist</text><text x=\"358\" y=\"78\">safe kind allowed</text></g></svg>"},{"alt":"Choice checklist.","caption":"Sort influence.","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 660 150\"><rect x=\"10\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#fff4ea\" stroke=\"#b87445\"/><rect x=\"340\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#e8f5ed\" stroke=\"#297a61\"/><g font-size=\"16\" fill=\"#263948\"><text x=\"28\" y=\"42\">Six scenarios</text><text x=\"28\" y=\"78\">checklist</text><text x=\"358\" y=\"42\">Risk</text><text x=\"358\" y=\"78\">everyone does it</text></g></svg>"}],"year_level":"Year 4"}') WHERE seed_key='s2-pdhpe-y4-w18-l1' AND family_id IS NULL;
